const gifts={
 games:{title:'A controller for his next adventure',icon:'🎮',tag:'FOR THE VIDEO GAME GUY',reason:'You picked video games. A comfortable controller is a gift he can reach for every time he plays.',note:'Before buying: check whether he plays on PC, PlayStation, Xbox, or Switch. Controllers are not universally compatible.',query:'gaming controller'},
 books:{title:'A character from his favorite world',icon:'📚',tag:'FOR THE FANTASY READER',reason:'You picked fantasy books. A character model brings a favorite story off the page and onto his shelf—think a Stormlight Archive collectible.',note:'Before buying: confirm he likes The Stormlight Archive and check the character, maker, and licensing of the model. This is a gift concept, not a verified listing.',query:'Stormlight Archive character figure'},
 dice:{title:'Dice worthy of his next campaign',icon:'🎲',tag:'FOR THE DUNGEON EXPLORER',reason:'You picked Dungeons & Dragons. A distinctive set of polyhedral dice adds a little personality to every roll.',note:'Before buying: look for a complete seven-piece set with easy-to-read numbers. Check whether he prefers resin or metal dice.',query:'Dungeons and Dragons polyhedral dice set'},
 pen:{title:'A bullet pen with a story to tell',icon:'🖊️',tag:'FOR THE HUNTING ENTHUSIAST',reason:'You said he enjoys hunting. A cartridge-style writing pen brings an outdoors-inspired detail to something he can use every day.',note:'Before buying: choose a finished writing pen, check the refill type, and confirm the materials with the seller. This recommendation is for a pen, not ammunition.',query:'bullet cartridge writing pen'}
};
let path=[];
const quiz=document.getElementById('quiz');
const steps={start:{title:'Would you consider your boyfriend nerdy?',intro:'The lovingly-knows-every-detail kind of nerdy.',choices:[['yes','Absolutely','He has his favorite worlds.','✦'],['no','Not really','His interests are somewhere else.','☀']]},nerdy:{title:'What does he geek out about?',intro:'Pick the one that sounds most like him.',choices:[['games','Video games','One more level. One more match.','🎮'],['books','Fantasy books','Just one more chapter.','📚'],['dice','Dungeons & Dragons','There’s always another campaign.','🎲']]},hunting:{title:'Is he into hunting?',intro:'Let’s explore his outdoorsy side.',choices:[['yes','Yes, that’s his thing','Time outdoors is time well spent.','🌲'],['no','No, not really','Let’s keep looking.','↗']]}};
function state(){if(!path.length)return 'start';if(path.length===1)return path[0]==='yes'?'nerdy':'hunting';return path[0]==='yes'?'result':path[1]==='yes'?'result':'empty'}
function pick(value){const s=state();if(!steps[s]||!steps[s].choices.some(c=>c[0]===value))throw new Error('Choose one of the available answers.');path.push(value);render();return {screen:state(),answers:[...path]}}
function reset(){path=[];render()}
function render(focus=true){const s=state(),step=steps[s];document.getElementById('step-label').textContent= s==='start'?'01 / GET TO KNOW HIM':step?'02 / FOLLOW HIS INTERESTS':s==='result'?'YOUR GIFT IDEA':'A DIFFERENT DIRECTION';document.getElementById('step-count').textContent=step?(s==='start'?'1 of 2':'2 of 2'):'Quiz complete';document.getElementById('progress-fill').style.width=s==='start'?'50%':'100%';document.getElementById('back').hidden=!path.length;
 if(step){quiz.innerHTML=`<h2 tabindex="-1">${step.title}</h2><p class="intro">${step.intro}</p><div class="choices">${step.choices.map(([value,title,desc,icon])=>`<button class="choice" data-answer="${value}"><span class="icon" aria-hidden="true">${icon}</span><span><strong>${title}</strong><small>${desc}</small></span><span class="arrow" aria-hidden="true">→</span></button>`).join('')}</div>`}
 else if(s==='result'){const g=gifts[path[0]==='yes'?path[1]:'pen'];quiz.innerHTML=`<span class="tag">${g.tag}</span><h2 tabindex="-1">${g.title}</h2><p class="reason">${g.reason}</p><div class="result-icon" aria-hidden="true">${g.icon}</div><p class="note">${g.note}</p><a class="primary" href="https://www.amazon.com/s?k=${encodeURIComponent(g.query)}" target="_blank" rel="noopener noreferrer">Explore options on Amazon ↗</a><p class="note">Sample recommendation. Opens Amazon search, not a specific product. No affiliate link or commission in this prototype.</p><button class="text-button restart" data-restart>Find another gift</button>`}
 else{quiz.innerHTML='<div class="empty-icon" aria-hidden="true">✳</div><h2 tabindex="-1">We haven’t found his thing. Yet.</h2><p class="intro">This early quiz covers gaming, fantasy books, Dungeons & Dragons, and hunting. More interests are on the way.</p><button class="primary" data-restart>Try another path</button>'}
 if(focus)quiz.querySelector('h2').focus({preventScroll:true});
}
quiz.addEventListener('click',event=>{const answer=event.target.closest('[data-answer]');if(answer)pick(answer.dataset.answer);if(event.target.closest('[data-restart]'))reset()});document.getElementById('back').addEventListener('click',()=>{path.pop();render()});render(false);
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'answer_gift_quiz',description:'Choose one available answer in the visible gift quiz.',inputSchema:{type:'object',properties:{answer:{type:'string',enum:['yes','no','games','books','dice']}},required:['answer'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>pick(input.answer)})).catch(()=>{});}catch{}}
